import { createServerFn } from '@tanstack/react-start'
import { defaultProjectData, normalizeProjectData } from '#/lib/project'
import * as store from './projects.server'

const MAX_DATA_CHARS = 2_000_000

function obj(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Neplatný vstup')
  return value as Record<string, unknown>
}

function str(value: unknown, field: string, max = 120) {
  if (typeof value !== 'string') throw new Error(`${field}: očakávaný text`)
  const s = value.trim()
  if (!s || s.length > max) throw new Error(`${field}: musí mať 1–${max} znakov`)
  return s
}

function int(value: unknown, field: string) {
  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) throw new Error(`${field}: očakávané číslo`)
  return value
}

function projectData(value: unknown) {
  if (JSON.stringify(value ?? null).length > MAX_DATA_CHARS) throw new Error('Projekt je príliš veľký')
  return normalizeProjectData(value)
}

const idInput = (d: unknown) => ({ id: str(obj(d).id, 'id', 64) })
const snapshotInput = (d: unknown) => ({ snapshotId: int(obj(d).snapshotId, 'snapshotId') })

export const listProjectsFn = createServerFn().handler(() => store.listProjects())

export const getProjectFn = createServerFn()
  .validator(idInput)
  .handler(({ data }) => store.getProject(data.id))

export const createProjectFn = createServerFn({ method: 'POST' })
  .validator((d: unknown) => {
    const o = obj(d)
    return { name: str(o.name, 'Názov'), data: o.data === undefined ? defaultProjectData() : projectData(o.data) }
  })
  .handler(({ data }) => store.createProject(data.name, data.data))

export const saveProjectFn = createServerFn({ method: 'POST' })
  .validator((d: unknown) => {
    const o = obj(d)
    return { id: str(o.id, 'id', 64), data: projectData(o.data), baseRevision: int(o.baseRevision, 'baseRevision') }
  })
  .handler(({ data }) => store.saveProject(data.id, data.data, data.baseRevision))

export const importIntoProjectFn = createServerFn({ method: 'POST' })
  .validator((d: unknown) => {
    const o = obj(d)
    return { id: str(o.id, 'id', 64), data: projectData(o.data), label: str(o.label, 'Popis', 200) }
  })
  .handler(({ data }) => store.replaceProjectData(data.id, data.data, data.label))

export const renameProjectFn = createServerFn({ method: 'POST' })
  .validator((d: unknown) => ({ ...idInput(d), name: str(obj(d).name, 'Názov') }))
  .handler(({ data }) => store.renameProject(data.id, data.name))

export const deleteProjectFn = createServerFn({ method: 'POST' })
  .validator(idInput)
  .handler(({ data }) => store.deleteProject(data.id))

export const duplicateProjectFn = createServerFn({ method: 'POST' })
  .validator(idInput)
  .handler(({ data }) => store.duplicateProject(data.id))

export const listSnapshotsFn = createServerFn()
  .validator(idInput)
  .handler(({ data }) => store.listSnapshots(data.id))

export const createSnapshotFn = createServerFn({ method: 'POST' })
  .validator((d: unknown) => ({ ...idInput(d), label: str(obj(d).label, 'Popis', 200) }))
  .handler(({ data }) => store.createSnapshot(data.id, data.label))

export const restoreSnapshotFn = createServerFn({ method: 'POST' })
  .validator(snapshotInput)
  .handler(({ data }) => store.restoreSnapshot(data.snapshotId))

export const deleteSnapshotFn = createServerFn({ method: 'POST' })
